/* eslint-env jest */
'use strict';

const os = require('os');

const yandexLogger = require('../../src');

describe('YandexLogger. Middleware. Bunyan', () => {
    let logger;
    let stream;
    let jestFakeTimers;

    beforeEach(() => {
        // Initialize a mock function to replace `write`.
        stream = { write: jest.fn() };

        logger = yandexLogger({
            streams: [
                { stream },
            ],
            middleware: [
                require('../../middleware/bunyan')(),
            ],
        });

        // Use fake timers and set the system time
        jestFakeTimers = jest.useFakeTimers('modern');
        jest.setSystemTime(1000);
    });

    afterEach(() => {
        jestFakeTimers.clearAllTimers();
    });

    it('должен добавить bunyan-специфичные поля в record', () => {
        logger.info('message');

        expect(stream.write).toHaveBeenCalledWith({
            pid: process.pid,
            date: expect.any(Date),
            name: 'yandex-logger',
            hostname: os.hostname(),
            level: 30,
            levelName: 'INFO',
            msg: 'message',
            msgFormat: 'message',
            msgArgs: [],
            time: expect.any(Date),
            v: 0,
        });

        // Checking the time field using Jest's mock.calls
        expect(stream.write.mock.calls[0][0].time.toISOString()).toBe('1970-01-01T00:00:01.000Z');

        expect(stream.write).toHaveBeenCalledTimes(1);
    });
});
